1	package calibrate
2	
3	import (
4		"path/filepath"
5		"strings"
6		"testing"
7		"time"
8	)
9	
10	// 本文件为“录入证书”的同号判定补充自动化回归保障，守住一条业务事实：
11	//
12	//	同一台账中，同一个证书编号只能对应一份已经保存的证书。
13	//
14	// 必须同时保护两个方向的既有行为，任何一侧被放宽或收紧都算回归：
15	//
16	//  1. 同号且全部业务内容一致：成功返回原证书并标明重复，历史仍只有原来那
17	//     一张，录入时间保留第一次成功保存的值；后一次提交发生在更晚的时间也
18	//     不能据此生成新证书。器具编号、证书编号、日期、方法、摘要前后的空白
19	//     沿用现有去除规则；数字写法不同但测得误差是同一个数值，仍是同一份
20	//     业务内容。方法或摘要内部的文字变化不能借去除空白被当成相同内容。
21	//  2. 同号但任一字段不同：明确报告编号冲突（ConflictError），而不是成功、
22	//     普通输入无效或保存失败，且绝不能用新内容悄悄替换原证书。比较必须
23	//     覆盖所属器具、校准日期、有效期截止日、校准方法、测得误差和摘要；
24	//     正负误差即使绝对值相同、合格结论相同，数值不同仍是冲突。
25	//
26	// 此外还要守住冲突提交没有任何副作用：冲突后按器具核对看到的原证书全部
27	// 内容、历史数量与最近证书选择都与提交前一致；把同号证书挂到另一件器具
28	// 时，目标器具不能多出这张证书；原证书超差时把误差改成合格值重交、原
29	// 证书已到期时把截止日改成未来重交，都不能解除或恢复使用资格。
30	
31	// sameNumberBaseInput 是同号判定回归的标准证书内容：校准日期早于假时钟的
32	// 本机今天，截止日晚于校准日期，误差有限，方法与摘要非空。
33	func sameNumberBaseInput() CertificateInput {
34		return CertificateInput{
35			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
36			Expiry: "2027-09-01", Method: "规范A", Error: 0.1, Summary: "摘要",
37		}
38	}
39	
40	// setupSameNumberLedger 准备一件已登记器具 M-1（允许误差 0.5）和另一件
41	// 已登记器具 M-2（用于“换到另一件器具”的合法变化），时钟拨到给定时刻。
42	func setupSameNumberLedger(t *testing.T, now time.Time) (*fakeClock, *Ledger) {
43		t.Helper()
44		clock := &fakeClock{t: now}
45		l := newTestLedger(t, clock)
46		mustRegister(t, l, "M-1", "万用表", 0.5)
47		mustRegister(t, l, "M-2", "示波器", 1.0)
48		return clock, l
49	}
50	
51	// assertStoredCertIntact 核对冲突提交后台账中仍只有原证书这一张，且全部
52	// 内容（含录入时间）与首次保存时完全一致，所属器具的历史数量与最近证书
53	// 选择也不变。
54	func assertStoredCertIntact(t *testing.T, l *Ledger, want Certificate) {
55		t.Helper()
56		stored := l.findCertificate(want.Number)
57		if stored == nil {
58			t.Fatalf("冲突提交后证书 %s 消失", want.Number)
59		}
60		if *stored != want {
61			t.Fatalf("冲突提交不得改动原证书：保存=%+v 期望=%+v", *stored, want)
62		}
63		if n := len(l.data.Certificates); n != 1 {
64			t.Fatalf("全台账应仍只有 1 张证书，得到 %d 张：%+v", n, l.data.Certificates)
65		}
66		if n := len(l.certificatesOf(want.InstrumentID)); n != 1 {
67			t.Fatalf("原器具 %s 的历史应仍只有 1 张证书，得到 %d 张",
68				want.InstrumentID, n)
69		}
70		latest := l.LatestCertificate(want.InstrumentID)
71		if latest == nil || *latest != want {
72			t.Fatalf("最近证书应仍是原证书 %s：%+v", want.Number, latest)
73		}
74	}
75	
76	// TestSameNumberSameContentReturnsOriginalAndKeepsFirstSaveTime 覆盖幂等主
77	// 场景：首次录入成功后，把时钟拨到另一个更晚的日历日期再提交相同编号与
78	// 相同业务内容，必须成功返回原证书、标明重复，不产生新证书、不刷新录入
79	// 时间。
80	func TestSameNumberSameContentReturnsOriginalAndKeepsFirstSaveTime(t *testing.T) {
81		firstClock := mustDate(t, "2026-09-01").Add(9 * time.Hour)
82		clock, l := setupSameNumberLedger(t, firstClock)
83	
84		in := sameNumberBaseInput()
85		first, dup, err := l.AddCertificate(in)
86		if err != nil || dup || first == nil {
87			t.Fatalf("首次录入应作为新证书成功：err=%v dup=%v cert=%v", err, dup, first)
88		}
89		if !strings.HasPrefix(first.CreatedAt, "2026-09-01T09:00") {
90			t.Fatalf("首次录入时间应取第一次成功保存的时刻，得到 %s", first.CreatedAt)
91		}
92	
93		// 后一次提交发生在不同时间（晚了一个多月）：内容相同只能返回原证书。
94		clock.t = mustDate(t, "2026-10-02").Add(15*time.Hour + 30*time.Minute)
95		again, isDup, err := l.AddCertificate(in)
96		if err != nil || !isDup || again == nil {
97			t.Fatalf("更晚时刻同号同内容应成功并标明重复：err=%v dup=%v cert=%v",
98				err, isDup, again)
99		}
100		if *again != *first {
101			t.Fatalf("重复提交应返回原证书全部内容：首次 %+v，再次 %+v", *first, *again)
102		}
103	
104		// 历史仍只有原来那一张；录入时间保留第一次成功保存的值。
105		assertStoredCertIntact(t, l, *first)
106		stored := l.findCertificate("C-1")
107		if stored.CreatedAt != first.CreatedAt {
108			t.Fatalf("录入时间必须保留首次保存值 %s，得到 %s",
109				first.CreatedAt, stored.CreatedAt)
110		}
111		if strings.HasPrefix(stored.CreatedAt, "2026-10-02") {
112			t.Fatalf("更晚的重复提交不能刷新录入时间，得到 %s", stored.CreatedAt)
113		}
114	}
115	
116	// TestSameNumberTrimsSurroundingWhitespaceButKeepsInternalText 保护“相同
117	// 内容”的归一化边界：器具编号、证书编号、日期、方法、摘要前后的空白沿用
118	// 现有 TrimSpace 规则后参与比较，测得误差只看数值（1e-1 与 0.1 是同一个
119	// float64）；但方法、摘要内部发生的文字（空白）变化不能被去除空白抹平，
120	// 必须报冲突。
121	func TestSameNumberTrimsSurroundingWhitespaceButKeepsInternalText(t *testing.T) {
122		_, l := setupSameNumberLedger(t, mustDate(t, "2026-09-01"))
123		in := sameNumberBaseInput()
124		first, _, err := l.AddCertificate(in)
125		if err != nil {
126			t.Fatalf("首次录入失败: %v", err)
127		}
128	
129		// 所有字段前后加空白（含制表符、换行），误差换一种数字写法：归一化后
130		// 与首次内容完全一致，必须幂等返回原证书。
131		padded := CertificateInput{
132			InstrumentID: "  M-1  ", Number: "\tC-1\t", CalDate: " 2026-09-01 ",
133			Expiry: "  2027-09-01  ", Method: "  规范A  ", Error: 1e-1, Summary: "摘要\n",
134		}
135		again, dup, err := l.AddCertificate(padded)
136		if err != nil || !dup {
137			t.Fatalf("前后空白被去除后内容一致应返回原证书：err=%v dup=%v", err, dup)
138		}
139		if *again != *first {
140			t.Fatalf("空白归一化后应返回原证书：首次 %+v，再次 %+v", *first, *again)
141		}
142		if n := len(l.data.Certificates); n != 1 {
143			t.Fatalf("幂等提交不应增加证书，得到 %d 张", n)
144		}
145	
146		// 方法内部插入空白：是不同的方法文字，不能借去除空白当成相同内容。
147		internalMethod := in
148		internalMethod.Method = "规范 A"
149		if _, _, err := l.AddCertificate(internalMethod); !IsConflict(err) {
150			t.Fatalf("方法内部文字变化应报编号冲突，得到 %v", err)
151		}
152		if got := l.findCertificate("C-1"); got.Method != "规范A" {
153			t.Fatalf("冲突后原方法被改动：%s", got.Method)
154		}
155	
156		// 摘要内部插入空白同理：是不同的摘要内容。
157		internalSummary := in
158		internalSummary.Summary = "摘 要"
159		if _, _, err := l.AddCertificate(internalSummary); !IsConflict(err) {
160			t.Fatalf("摘要内部文字变化应报编号冲突，得到 %v", err)
161		}
162		if got := l.findCertificate("C-1"); got.Summary != "摘要" {
163			t.Fatalf("冲突后原摘要被改动：%s", got.Summary)
164		}
165		assertStoredCertIntact(t, l, *first)
166	}
167	
168	// TestSameNumberEachFieldChangeAloneIsConflictNotRejection 逐字段保护比较
169	// 范围：所属器具、校准日期、有效期截止日、校准方法、测得误差、摘要中的
170	// 任意一项变化（每项都换成本身合法的内容），都必须明确报告编号冲突，而
171	// 不是成功或普通输入无效；原证书全部内容、历史数量与最近证书不变，挂到
172	// 另一件器具时目标器具也不能多出这张同号证书。
173	func TestSameNumberEachFieldChangeAloneIsConflictNotRejection(t *testing.T) {
174		cases := []struct {
175			name string
176			mut  func(*CertificateInput)
177		}{
178			{"所属器具换成另一件已登记器具", func(c *CertificateInput) { c.InstrumentID = "M-2" }},
179			{"校准日期换成真实且不晚于今天的日期", func(c *CertificateInput) { c.CalDate = "2026-08-15" }},
180			{"有效期截止日换成更晚的真实日期", func(c *CertificateInput) { c.Expiry = "2028-09-01" }},
181			{"校准方法换成另一个非空方法", func(c *CertificateInput) { c.Method = "规范B" }},
182			{"测得误差换成另一个有限数值", func(c *CertificateInput) { c.Error = 0.2 }},
183			{"摘要换成另一段非空摘要", func(c *CertificateInput) { c.Summary = "另一份摘要" }},
184			{"方法内部空白变化", func(c *CertificateInput) { c.Method = "规范 A" }},
185			{"摘要内部空白变化", func(c *CertificateInput) { c.Summary = "摘 要" }},
186		}
187		for _, tc := range cases {
188			t.Run(tc.name, func(t *testing.T) {
189				_, l := setupSameNumberLedger(t, mustDate(t, "2026-10-02"))
190				base := sameNumberBaseInput()
191				first, _, err := l.AddCertificate(base)
192				if err != nil {
193					t.Fatalf("首次录入失败: %v", err)
194				}
195	
196				changed := base
197				tc.mut(&changed)
198				cert, dup, err := l.AddCertificate(changed)
199				if err == nil {
200					t.Fatalf("单字段变化必须被拒绝，却返回了证书 %+v（dup=%v）", cert, dup)
201				}
202				if !IsConflict(err) {
203					t.Fatalf("合法的单字段变化应报编号冲突，而不是普通输入无效或其他错误：%v", err)
204				}
205				if IsValidation(err) {
206					t.Fatalf("编号冲突不能被降级成普通输入无效：%v", err)
207				}
208				if cert != nil || dup {
209					t.Fatalf("冲突时不得返回成功或重复证书：cert=%v dup=%v", cert, dup)
210				}
211				if !strings.Contains(err.Error(), "C-1") ||
212					!strings.Contains(err.Error(), "内容不同") {
213					t.Fatalf("冲突信息应指出编号与内容不同，得到 %q", err.Error())
214				}
215	
216				// 原证书全部内容、历史数量与最近证书保持提交前一致。
217				assertStoredCertIntact(t, l, *first)
218				// 同号证书不能出现在目标器具 M-2 名下（即使本次提交挂到了 M-2）。
219				if n := len(l.certificatesOf("M-2")); n != 0 {
220					t.Fatalf("目标器具 M-2 不能多出这张同号证书，得到 %d 张", n)
221				}
222				if latest := l.LatestCertificate("M-2"); latest != nil {
223					t.Fatalf("目标器具 M-2 不应出现最近证书：%+v", latest)
224				}
225			})
226		}
227	}
228	
229	// TestSameNumberRepeatedConflictsNeverAccumulate 模拟调用方拿着同号内容
230	// 连续尝试多种合法变化：每一次都报冲突，任何一次都不能把新内容写进台账，
231	// 多轮冲突之后全台账仍只有首次保存的那一张。
232	func TestSameNumberRepeatedConflictsNeverAccumulate(t *testing.T) {
233		_, l := setupSameNumberLedger(t, mustDate(t, "2026-10-02"))
234		base := sameNumberBaseInput()
235		first, _, err := l.AddCertificate(base)
236		if err != nil {
237			t.Fatalf("首次录入失败: %v", err)
238		}
239	
240		mutations := []func(*CertificateInput){
241			func(c *CertificateInput) { c.InstrumentID = "M-2" },
242			func(c *CertificateInput) { c.CalDate = "2026-08-15" },
243			func(c *CertificateInput) { c.Expiry = "2028-09-01" },
244			func(c *CertificateInput) { c.Method = "规范B" },
245			func(c *CertificateInput) { c.Error = 0.2 },
246			func(c *CertificateInput) { c.Summary = "另一份摘要" },
247		}
248		for i, mut := range mutations {
249			changed := base
250			mut(&changed)
251			if _, _, err := l.AddCertificate(changed); !IsConflict(err) {
252				t.Fatalf("第 %d 次变化应报冲突，得到 %v", i+1, err)
253			}
254		}
255		assertStoredCertIntact(t, l, *first)
256		if n := len(l.certificatesOf("M-2")); n != 0 {
257			t.Fatalf("多轮冲突后目标器具 M-2 仍不应有证书，得到 %d 张", n)
258		}
259	}
260	
261	// TestSameNumberSignedErrorDifferenceIsConflictEvenWhenVerdictSame 专门保护
262	// 测得误差的符号：原证书误差 -0.4（在允许误差 0.5 内，合格），重交 +0.4，
263	// 两者绝对值相同、合格结论也相同，但数值不同，仍属于内容冲突，原误差的
264	// 符号必须保留；只有逐字节相同的 -0.4 重交才是重复提交。
265	func TestSameNumberSignedErrorDifferenceIsConflictEvenWhenVerdictSame(t *testing.T) {
266		_, l := setupSameNumberLedger(t, mustDate(t, "2026-10-02"))
267		in := sameNumberBaseInput()
268		in.Error = -0.4
269		first, _, err := l.AddCertificate(in)
270		if err != nil {
271			t.Fatalf("首次录入失败: %v", err)
272		}
273		if !first.Pass(0.5) {
274			t.Fatalf("前置条件失效：-0.4 应在允许误差 0.5 内判合格")
275		}
276	
277		// 绝对值相同、结论相同的反号误差：仍是冲突，不能替换原证书。
278		flipped := in
279		flipped.Error = 0.4
280		cert, dup, err := l.AddCertificate(flipped)
281		if !IsConflict(err) || cert != nil || dup {
282			t.Fatalf("反号误差应报冲突且不返回证书：err=%v cert=%v dup=%v", err, cert, dup)
283		}
284		if got := l.findCertificate("C-1"); got.Error != -0.4 {
285			t.Fatalf("原误差符号必须保留为 -0.4，得到 %g", got.Error)
286		}
287	
288		// 控制对照：逐字节相同的 -0.4 重交仍是幂等重复。
289		again, isDup, err := l.AddCertificate(in)
290		if err != nil || !isDup || again.Error != -0.4 {
291			t.Fatalf("相同数值重交应幂等返回原证书：err=%v dup=%v cert=%+v", err, isDup, again)
292		}
293		assertStoredCertIntact(t, l, *first)
294	}
295	
296	// TestSameNumberConflictUntouchedAfterReopen 保护“冲突不写盘”跨进程成立：
297	// 首次证书保存进文件后，连续发起多次同号内容不同的提交（全部被冲突拒绝），
298	// 用同一时刻重新打开台账文件，原证书全部内容、历史数量与最近证书选择仍与
299	// 首次保存一致，目标器具也没有多出证书。
300	func TestSameNumberConflictUntouchedAfterReopen(t *testing.T) {
301		path := filepath.Join(t.TempDir(), "ledger.json")
302		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
303		l, err := openAt(path, clock.now)
304		if err != nil {
305			t.Fatalf("open: %v", err)
306		}
307		mustRegister(t, l, "M-1", "万用表", 0.5)
308		mustRegister(t, l, "M-2", "示波器", 1.0)
309		base := sameNumberBaseInput()
310		first, _, err := l.AddCertificate(base)
311		if err != nil {
312			t.Fatalf("首次录入失败: %v", err)
313		}
314	
315		mutated := []CertificateInput{
316			func() CertificateInput { c := base; c.InstrumentID = "M-2"; return c }(),
317			func() CertificateInput { c := base; c.CalDate = "2026-08-15"; return c }(),
318			func() CertificateInput { c := base; c.Expiry = "2028-09-01"; return c }(),
319			func() CertificateInput { c := base; c.Method = "规范B"; return c }(),
320			func() CertificateInput { c := base; c.Error = 0.2; return c }(),
321			func() CertificateInput { c := base; c.Summary = "另一份摘要"; return c }(),
322		}
323		for i, in := range mutated {
324			if _, _, err := l.AddCertificate(in); !IsConflict(err) {
325				t.Fatalf("第 %d 次变化应报冲突，得到 %v", i+1, err)
326			}
327		}
328	
329		reopened, err := openAt(path, clock.now)
330		if err != nil {
331			t.Fatalf("reopen: %v", err)
332		}
333		if n := len(reopened.data.Certificates); n != 1 {
334			t.Fatalf("重开后应仍只有 1 张证书，得到 %d 张：%+v", n, reopened.data.Certificates)
335		}
336		stored := reopened.findCertificate("C-1")
337		if stored == nil || *stored != *first {
338			t.Fatalf("重开后原证书内容被改动：stored=%+v want=%+v", stored, first)
339		}
340		if n := len(reopened.certificatesOf("M-1")); n != 1 {
341			t.Fatalf("重开后原器具历史应仍为 1 张，得到 %d", n)
342		}
343		if n := len(reopened.certificatesOf("M-2")); n != 0 {
344			t.Fatalf("重开后目标器具 M-2 不应出现同号证书，得到 %d 张", n)
345		}
346		latest := reopened.LatestCertificate("M-1")
347		if latest == nil || latest.Number != "C-1" {
348			t.Fatalf("重开后最近证书应仍是 C-1：%+v", latest)
349		}
350	}
351	
352	// TestSameNumberConflictCannotLiftFailOrExpiryRestriction 保护冲突提交不能
353	// 改变使用资格：原证书超差时，把同号证书的误差改成合格值重交不能解除超差
354	// 限制；原证书已到期时，把截止日改成未来日期重交不能恢复使用资格。两次
355	// 重交内容本身都合法，结果只能是编号冲突。
356	func TestSameNumberConflictCannotLiftFailOrExpiryRestriction(t *testing.T) {
357		t.Run("超差证书改成合格值重交不能解除限制", func(t *testing.T) {
358			_, l := setupSameNumberLedger(t, mustDate(t, "2026-10-02"))
359			if err := l.SetStatus("M-1", StatusInUse); err != nil {
360				t.Fatalf("切换在用: %v", err)
361			}
362			bad := sameNumberBaseInput()
363			bad.Error = 0.8 // 绝对值超过 0.5：超差，但截止日仍在未来。
364			first, _, err := l.AddCertificate(bad)
365			if err != nil {
366				t.Fatalf("超差证书录入失败: %v", err)
367			}
368			before, _ := l.CanUse("M-1")
369			if before.Allowed || !containsReason(before.Reasons, "超差") {
370				t.Fatalf("前置条件失效：应因超差被限制，得到 %v", before.Reasons)
371			}
372	
373			// 用同号、合格误差重交：内容本身合法，只能报冲突。
374			good := bad
375			good.Error = 0.1
376			cert, dup, err := l.AddCertificate(good)
377			if !IsConflict(err) || cert != nil || dup {
378				t.Fatalf("合格值重交超差证书应报冲突：err=%v cert=%v dup=%v", err, cert, dup)
379			}
380	
381			// 限制不被解除：最近证书仍是误差 0.8 的原证书，申请使用仍只因超差被拒。
382			after, _ := l.CanUse("M-1")
383			if after.Allowed || !containsReason(after.Reasons, "超差") {
384				t.Fatalf("冲突重交不能解除超差限制：allowed=%v reasons=%v",
385					after.Allowed, after.Reasons)
386			}
387			if containsReason(after.Reasons, "到期") {
388				t.Fatalf("未来截止日的证书不应混入到期原因：%v", after.Reasons)
389			}
390			rec, err := l.RequestUse("M-1")
391			if err != nil || rec.Allowed || !containsReason(rec.Reasons, "超差") {
392				t.Fatalf("正式申请仍应因原超差证书被拒：err=%v rec=%+v", err, rec)
393			}
394			assertStoredCertIntact(t, l, *first)
395		})
396	
397		t.Run("到期证书改成未来截止日重交不能恢复资格", func(t *testing.T) {
398			_, l := setupSameNumberLedger(t, mustDate(t, "2026-10-02"))
399			if err := l.SetStatus("M-1", StatusInUse); err != nil {
400				t.Fatalf("切换在用: %v", err)
401			}
402			expired := sameNumberBaseInput()
403			expired.CalDate = "2025-01-01"
404			expired.Expiry = "2025-12-31" // 早于本机今天 2026-10-02，已到期。
405			expired.Error = 0.1           // 误差合格：限制只应来自到期。
406			first, _, err := l.AddCertificate(expired)
407			if err != nil {
408				t.Fatalf("到期证书录入失败: %v", err)
409			}
410			before, _ := l.CanUse("M-1")
411			if before.Allowed || !containsReason(before.Reasons, "到期") {
412				t.Fatalf("前置条件失效：应因到期被限制，得到 %v", before.Reasons)
413			}
414	
415			// 用同号、未来截止日（仍晚于校准日期，本身合法）重交：只能报冲突。
416			updated := expired
417			updated.Expiry = "2028-01-01"
418			cert, dup, err := l.AddCertificate(updated)
419			if !IsConflict(err) || cert != nil || dup {
420				t.Fatalf("未来截止日重交到期证书应报冲突：err=%v cert=%v dup=%v", err, cert, dup)
421			}
422	
423			// 使用资格不恢复：最近证书仍是已到期的原证书，申请使用仍只因到期被拒。
424			after, _ := l.CanUse("M-1")
425			if after.Allowed || !containsReason(after.Reasons, "到期") {
426				t.Fatalf("冲突重交不能恢复使用资格：allowed=%v reasons=%v",
427					after.Allowed, after.Reasons)
428			}
429			if containsReason(after.Reasons, "超差") {
430				t.Fatalf("合格证书不应混入超差原因：%v", after.Reasons)
431			}
432			if after.Latest == nil || after.Latest.Expiry != "2025-12-31" || !after.Latest.Pass {
433				t.Fatalf("最近证书应仍是合格但已到期的原证书：%+v", after.Latest)
434			}
435			rec, err := l.RequestUse("M-1")
436			if err != nil || rec.Allowed || !containsReason(rec.Reasons, "到期") {
437				t.Fatalf("正式申请仍应因原证书到期被拒：err=%v rec=%+v", err, rec)
438			}
439			assertStoredCertIntact(t, l, *first)
440		})
441	}
442

