27	// sameNumberCertArgs 构造一条可指定全部字段的证书录入命令，便于只改一个
28	// 字段重交同号证书。
29	func sameNumberCertArgs(path, instrument, number, calDate, expiry, method, errVal, summary string) []string {
30		return []string{"cert", "-f", path,
31			"--instrument", instrument, "--number", number,
32			"--cal-date", calDate, "--expiry", expiry,
33			"--method", method, "--error", errVal, "--summary", summary}
34	}
