36	// persistedCert 是台账文件、cert 成功响应与 review 视图里证书共用的字段。
37	type persistedCert struct {
38		Number       string  `json:"number"`
39		InstrumentID string  `json:"instrument_id"`
40		CalDate      string  `json:"cal_date"`
41		Expiry       string  `json:"expiry"`
42		Method       string  `json:"method"`
43		Error        float64 `json:"error"`
44		Summary      string  `json:"summary"`
45		CreatedAt    string  `json:"created_at"`
46	}
