48	// readPersistedCerts 直接读台账文件中已保存的全部证书（按文件原顺序）。
49	func readPersistedCerts(t *testing.T, path string) []persistedCert {
50		t.Helper()
51		raw, err := os.ReadFile(path)
52		if err != nil {
53			t.Fatalf("读取台账 %s: %v", path, err)
54		}
55		var data struct {
56			Certificates []persistedCert `json:"certificates"`
57		}
58		if err := json.Unmarshal(raw, &data); err != nil {
59			t.Fatalf("解析台账 %s: %v", path, err)
60		}
61		return data.Certificates
62	}
63	
64	// rewritePersistedCertField 直接改写台账文件中某张证书的单个字段，用来在
65	// 黑盒测试里模拟“首次保存发生在更早时间”这类无法靠等待得到的状态，其余
66	// 历史原样保留。
67	func rewritePersistedCertField(t *testing.T, path, number, field string, value any) {
68		t.Helper()
69		raw, err := os.ReadFile(path)
70		if err != nil {
71			t.Fatalf("读取台账 %s: %v", path, err)
72		}
73		var data map[string]any
74		if err := json.Unmarshal(raw, &data); err != nil {
75			t.Fatalf("解析台账 %s: %v", path, err)
76		}
77		certs, _ := data["certificates"].([]any)
78		found := false
79		for _, item := range certs {
80			c, _ := item.(map[string]any)
81			if c["number"] == number {
82				c[field] = value
83				found = true
84			}
85		}
86		if !found {
87			t.Fatalf("台账中找不到证书 %s，无法改写字段 %s", number, field)
88		}
89		out, err := json.MarshalIndent(data, "", "  ")
90		if err != nil {
91			t.Fatalf("序列化台账: %v", err)
92		}
93		if err := os.WriteFile(path, append(out, '\n'), 0o644); err != nil {
94			t.Fatalf("写回台账 %s: %v", path, err)
95		}
96	}
