98	// certCLIResponse 是 cert 命令 --json 输出的最小解析：成功时有 certificate，
99	// 冲突/校验拒绝时 accepted=false 且没有 certificate。
100	type certCLIResponse struct {
101		Accepted    bool           `json:"accepted"`
102		Duplicate   bool           `json:"duplicate"`
103		Conflict    bool           `json:"conflict"`
104		Verdict     string         `json:"verdict"`
105		Error       string         `json:"error"`
106		Certificate *persistedCert `json:"certificate"`
107	}
