112		var resp certCLIResponse
113		if r.code == 0 || strings.Contains(r.stdout, "accepted") {
114			if err := json.Unmarshal([]byte(r.stdout), &resp); err != nil {
115				t.Fatalf("cert JSON 解析失败: %v\n%s", err, r.stdout)
116			}
117		}
118		return r, resp
