139			t.Fatalf("review %s 失败 code=%d stderr=%s", id, r.code, r.stderr)
140		}
141		var v sameNumberReview
142		if err := json.Unmarshal([]byte(r.stdout), &v); err != nil {
143			t.Fatalf("review JSON 解析失败: %v\n%s", err, r.stdout)
144		}
145		return v
