148	// TestCLISameNumberSameContentReturnsOriginalAndKeepsFirstSaveTime 是命令行
149	// 幂等主场景：首次录入成功后，在另一个时间提交相同编号与相同业务内容，
150	// 普通输出与 JSON 都退出 0、明确重复并返回原证书；历史仍是一张，录入时间
151	// 保留第一次成功保存的值（这里把台账中的录入时间拨到更早来确定性地模拟
152	// “两次提交发生在不同时间”），不会生成新证书。
153	func TestCLISameNumberSameContentReturnsOriginalAndKeepsFirstSaveTime(t *testing.T) {
154		dir := chdirTemp(t)
155		path := filepath.Join(dir, "台账.json")
156		registerAllowed(t, path, "M-1", "0.5")
157	
158		now := time.Now()
159		cal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
160		future := now.AddDate(1, 0, 0).Format(calibrate.DateLayout)
161		args := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范A", "0.1", "摘要")
162	
163		first := runArgs(t, args...)
164		if first.code != 0 || !strings.Contains(first.stdout, "已录入新证书") {
165			t.Fatalf("首次应作为新证书录入成功：code=%d stdout=%q stderr=%s",
166				first.code, first.stdout, first.stderr)
167		}
168	
169		// 确定性模拟“首次成功保存发生在更早时间”：把录入时间拨到 2020 年。
170		const firstSave = "2020-01-01T08:00:00Z"
171		rewritePersistedCertField(t, path, "C-1", "created_at", firstSave)
172	
173		// 普通输出重交：退出 0，明确重复、不增加历史，且不是“已录入新证书”。
174		human := runArgs(t, args...)
175		if human.code != 0 {
176			t.Fatalf("同号同内容应退出 0，得到 %d（stderr=%s）", human.code, human.stderr)
177		}
178		if !strings.Contains(human.stdout, "同号证书且内容一致，返回原证书，未增加历史记录") {
179			t.Fatalf("普通输出应明确返回原证书且未增加历史：%q", human.stdout)
180		}
181		if strings.Contains(human.stdout, "已录入新证书") {
182			t.Fatalf("重复提交不能被说成录入新证书：%q", human.stdout)
183		}
184		if !strings.Contains(human.stdout, "C-1") || !strings.Contains(human.stdout, "判定：合格") {
185			t.Fatalf("普通输出应展示原证书编号与结论：%q", human.stdout)
186		}
187	
188		// JSON 重交：accepted=true、duplicate=true，返回原证书，录入时间不被刷新。
189		js, resp := runCertCLIJSON(t, args)
190		if js.code != 0 {
191			t.Fatalf("JSON 同号同内容应退出 0，得到 %d（stderr=%s）", js.code, js.stderr)
192		}
193		if !resp.Accepted || !resp.Duplicate || resp.Conflict {
194			t.Fatalf("JSON 应 accepted=true duplicate=true conflict=false，得到 %+v", resp)
195		}
196		if resp.Certificate == nil {
197			t.Fatal("重复提交应返回原证书内容")
198		}
199		want := persistedCert{
200			Number: "C-1", InstrumentID: "M-1", CalDate: cal, Expiry: future,
201			Method: "规范A", Error: 0.1, Summary: "摘要", CreatedAt: firstSave,
202		}
203		if *resp.Certificate != want {
