223	// TestCLISameNumberWhitespaceAndNumberFormsNormalized 保护“相同内容”的
224	// 归一化边界：器具编号、证书编号、日期、方法、摘要前后的空白沿用现有去除
225	// 规则，误差换一种数字写法（1e-1 即 0.1）仍是同一数值——这些重交都算
226	// 重复；但方法、摘要内部的文字（空白）变化不能被去除空白抹平，必须冲突。
227	func TestCLISameNumberWhitespaceAndNumberFormsNormalized(t *testing.T) {
228		dir := chdirTemp(t)
229		path := filepath.Join(dir, "台账.json")
230		registerAllowed(t, path, "M-1", "0.5")
231	
232		now := time.Now()
233		cal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
234		future := now.AddDate(1, 0, 0).Format(calibrate.DateLayout)
235		base := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范A", "0.1", "摘要")
236		if r := runArgs(t, base...); r.code != 0 {
237			t.Fatalf("首次录入失败 code=%d stderr=%s", r.code, r.stderr)
238		}
239	
240		// 前后空白 + 误差科学计数法：归一化后与原内容一致，按重复返回。
241		padded := sameNumberCertArgs(path, "  M-1  ", "\tC-1\t", " "+cal+" ",
242			"  "+future+"  ", " 规范A\t", "1e-1", "摘要\n")
243		r, resp := runCertCLIJSON(t, padded)
244		if r.code != 0 || !resp.Accepted || !resp.Duplicate {
245			t.Fatalf("前后空白被去除、误差数值相同应判重复：code=%d resp=%+v stderr=%s",
246				r.code, resp, r.stderr)
247		}
248		if resp.Certificate == nil || resp.Certificate.Method != "规范A" ||
249			resp.Certificate.Summary != "摘要" || resp.Certificate.Error != 0.1 ||
250			resp.Certificate.InstrumentID != "M-1" || resp.Certificate.CalDate != cal {
251			t.Fatalf("归一化后应返回原证书内容：%+v", resp.Certificate)
252		}
253		if n := len(readPersistedCerts(t, path)); n != 1 {
254			t.Fatalf("归一化重复提交不应增加证书，得到 %d 张", n)
255		}
256	
257		// 方法内部空白变化：是不同的方法文字，必须冲突而非重复。
258		methodInside := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范 A", "0.1", "摘要")
259		if r := runArgs(t, methodInside...); r.code != 1 ||
260			!strings.Contains(r.stderr, "已拒绝") || !strings.Contains(r.stderr, "内容不同") {
261			t.Fatalf("方法内部文字变化应冲突退出 1：code=%d stderr=%q", r.code, r.stderr)
262		}
263		// 摘要内部空白变化同理。
264		summaryInside := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范A", "0.1", "摘 要")
265		jr, jresp := runCertCLIJSON(t, summaryInside)
266		if jr.code != 1 || jresp.Accepted || !jresp.Conflict {
267			t.Fatalf("摘要内部文字变化应冲突：code=%d resp=%+v", jr.code, jresp)
268		}
269		if jresp.Certificate != nil {
270			t.Fatalf("冲突不能返回录入成功的证书：%+v", jresp.Certificate)
271		}
272	
273		// 两次内部变化后原方法、原摘要与证书数量都不变。
274		certs := readPersistedCerts(t, path)
275		if len(certs) != 1 || certs[0].Method != "规范A" || certs[0].Summary != "摘要" {
276			t.Fatalf("内部空白冲突不得改动原证书：%+v", certs)
277		}
278	}
279	
280	// TestCLISameNumberEachFieldChangeReportedConflict 逐字段保护比较范围：
281	// 所属器具、校准日期、有效期截止日、校准方法、测得误差、摘要各自单独换成
282	// 本身合法的内容，普通输出与 JSON 都必须报编号冲突（退出 1、conflict=true），
283	// 而不是成功或普通输入无效；原证书内容、历史数量、最近证书不变，挂到
284	// 另一件器具时目标器具也不能多出这张证书。
285	func TestCLISameNumberEachFieldChangeReportedConflict(t *testing.T) {
286		now := time.Now()
287		cal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
288		calOther := now.AddDate(0, 0, -45).Format(calibrate.DateLayout)
289		future := now.AddDate(1, 0, 0).Format(calibrate.DateLayout)
290		futureOther := now.AddDate(2, 0, 0).Format(calibrate.DateLayout)
291	
292		cases := []struct {
293			name  string
294			build func(path string) []string
295		}{
296			{"所属器具换成另一件已登记器具",
297				func(p string) []string {
298					return sameNumberCertArgs(p, "M-2", "C-1", cal, future, "规范A", "0.1", "摘要")
299				}},
300			{"校准日期换成真实且不晚于今天的日期",
301				func(p string) []string {
302					return sameNumberCertArgs(p, "M-1", "C-1", calOther, future, "规范A", "0.1", "摘要")
303				}},
304			{"有效期截止日换成更晚的真实日期",
305				func(p string) []string {
306					return sameNumberCertArgs(p, "M-1", "C-1", cal, futureOther, "规范A", "0.1", "摘要")
307				}},
308			{"校准方法换成另一个非空方法",
309				func(p string) []string {
310					return sameNumberCertArgs(p, "M-1", "C-1", cal, future, "规范B", "0.1", "摘要")
311				}},
312			{"测得误差换成另一个有限数值",
313				func(p string) []string {
314					return sameNumberCertArgs(p, "M-1", "C-1", cal, future, "规范A", "0.2", "摘要")
315				}},
316			{"摘要换成另一段非空摘要",
317				func(p string) []string {
318					return sameNumberCertArgs(p, "M-1", "C-1", cal, future, "规范A", "0.1", "另一份摘要")
319				}},
320		}
321		for _, tc := range cases {
322			t.Run(tc.name, func(t *testing.T) {
323				dir := chdirTemp(t)
324				path := filepath.Join(dir, "台账.json")
325				registerAllowed(t, path, "M-1", "0.5")
326				registerAllowed(t, path, "M-2", "1")
327	
328				base := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范A", "0.1", "摘要")
329				if r := runArgs(t, base...); r.code != 0 {
330					t.Fatalf("首次录入失败 code=%d stderr=%s", r.code, r.stderr)
331				}
332				want := readPersistedCerts(t, path)[0]
333				changed := tc.build(path)
334	
335				// 普通输出：退出 1，以“已拒绝”说明编号冲突。
336				human := runArgs(t, changed...)
337				if human.code != 1 {
338					t.Fatalf("单字段变化应退出 1，得到 %d", human.code)
339				}
340				if !strings.Contains(human.stderr, "已拒绝") ||
341					!strings.Contains(human.stderr, "C-1") ||
342					!strings.Contains(human.stderr, "内容不同") {
343					t.Fatalf("普通输出应说明证书 C-1 编号冲突：%q", human.stderr)
344				}
345	
346				// JSON：退出 1、accepted=false、conflict=true，且不返回证书。
347				jr, jresp := runCertCLIJSON(t, changed)
348				if jr.code != 1 {
349					t.Fatalf("JSON 单字段变化应退出 1，得到 %d", jr.code)
350				}
351				if jresp.Accepted || !jresp.Conflict {
352					t.Fatalf("JSON 应明确未接受且属于冲突（区别于普通输入无效）：%+v", jresp)
353				}
354				if strings.Contains(jr.stdout, `"certificate"`) {
355					t.Fatalf("冲突时不得返回录入成功的证书：%s", jr.stdout)
356				}
357	
358				// 原证书全部内容与数量不变。
359				certs := readPersistedCerts(t, path)
360				if len(certs) != 1 || certs[0] != want {
361					t.Fatalf("冲突提交不得改动原证书或增加记录：got=%+v want=%+v",
362						certs, want)
363				}
364				rv := reviewSameNumberJSON(t, path, "M-1")
365				if len(rv.History) != 1 || rv.Latest == nil ||
366					rv.Latest.Number != "C-1" || rv.Latest.Error != 0.1 ||
367					rv.Latest.Method != "规范A" || rv.Latest.Summary != "摘要" ||
368					rv.Latest.CalDate != cal || rv.Latest.Expiry != future {
369					t.Fatalf("冲突后 M-1 的历史与最近证书应与提交前一致：%+v", rv)
370				}
371				// 目标器具 M-2 不能多出这张同号证书。
372				target := reviewSameNumberJSON(t, path, "M-2")
373				if len(target.History) != 0 || target.Latest != nil {
374					t.Fatalf("目标器具 M-2 不能多出同号证书：%+v", target)
375				}
376			})
377		}
378	}
379	
380	// TestCLISameNumberSignedErrorDifferenceConflict 专门保护误差符号：-0.4 与
381	// +0.4 绝对值相同、在允许误差 0.5 下结论同为合格，但数值不同仍属冲突；
382	// 只有逐字相同的 -0.4 重交才算重复。
383	func TestCLISameNumberSignedErrorDifferenceConflict(t *testing.T) {
384		dir := chdirTemp(t)
385		path := filepath.Join(dir, "台账.json")
386		registerAllowed(t, path, "M-1", "0.5")
387	
388		now := time.Now()
389		cal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
390		future := now.AddDate(1, 0, 0).Format(calibrate.DateLayout)
391		neg := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范A", "-0.4", "摘要")
392		if r := runArgs(t, neg...); r.code != 0 ||
393			!strings.Contains(r.stdout, "判定：合格") {
394			t.Fatalf("-0.4 证书应录入成功且合格：code=%d %q %s", r.code, r.stdout, r.stderr)
395		}
396	
397		// 反号误差：普通与 JSON 都必须冲突。
398		pos := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范A", "0.4", "摘要")
399		human := runArgs(t, pos...)
400		if human.code != 1 || !strings.Contains(human.stderr, "内容不同") {
401			t.Fatalf("反号误差应冲突退出 1：code=%d stderr=%q", human.code, human.stderr)
402		}
403		jr, jresp := runCertCLIJSON(t, pos)
404		if jr.code != 1 || jresp.Accepted || !jresp.Conflict || jresp.Certificate != nil {
405			t.Fatalf("反号误差 JSON 应冲突且不返回证书：code=%d resp=%+v", jr.code, jresp)
406		}
407		certs := readPersistedCerts(t, path)
408		if len(certs) != 1 || certs[0].Error != -0.4 {
409			t.Fatalf("原误差符号必须保留为 -0.4：%+v", certs)
410		}
411	
412		// 控制对照：相同的 -0.4 重交仍是幂等重复。
413		again, dup := runCertCLIJSON(t, neg)
414		if again.code != 0 || !dup.Accepted || !dup.Duplicate ||
415			dup.Certificate == nil || dup.Certificate.Error != -0.4 {
416			t.Fatalf("相同 -0.4 重交应幂等返回原证书：code=%d resp=%+v", again.code, dup)
417		}
418		if n := len(readPersistedCerts(t, path)); n != 1 {
419			t.Fatalf("整轮操作后应仍只有 1 张证书，得到 %d 张", n)
420		}
421	}
422	
423	// TestCLISameNumberConflictCannotLiftFailOrExpiryRestriction 保护冲突提交不
424	// 能改变使用资格：原证书超差时改成合格值重交、原证书已到期时改成未来截止
425	// 日重交，内容本身都合法，但只能报编号冲突；按器具核对看到的结论、历史
426	// 数量、最近证书与使用限制都与提交前一致，同号证书不会被换内容而生效。
427	func TestCLISameNumberConflictCannotLiftFailOrExpiryRestriction(t *testing.T) {
428		t.Run("超差证书改成合格值重交不能解除限制", func(t *testing.T) {
429			dir := chdirTemp(t)
430			path := filepath.Join(dir, "台账.json")
431			registerAllowed(t, path, "M-1", "0.5")
432			if r := runArgs(t, "status", "-f", path, "--id", "M-1", "--status", "在用"); r.code != 0 {
433				t.Fatalf("切换在用失败 code=%d stderr=%s", r.code, r.stderr)
434			}
435			now := time.Now()
436			cal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
437			future := now.AddDate(1, 0, 0).Format(calibrate.DateLayout)
438			bad := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范A", "0.8", "摘要")
439			if r := runArgs(t, bad...); r.code != 0 ||
440				!strings.Contains(r.stdout, "判定：超差") {
441				t.Fatalf("超差证书应录入成功并显示超差：code=%d %q %s", r.code, r.stdout, r.stderr)
442			}
443			if u := runArgs(t, "use", "--id", "M-1", "-f", path); u.code != 1 ||
444				!strings.Contains(u.stderr, "超差") {
445				t.Fatalf("前置条件失效：应因最近证书超差被拒，code=%d stderr=%q",
446					u.code, u.stderr)
447			}
448	
449			// 同号改成合格误差重交：只能报冲突。
450			good := sameNumberCertArgs(path, "M-1", "C-1", cal, future, "规范A", "0.1", "摘要")
451			jr, jresp := runCertCLIJSON(t, good)
452			if jr.code != 1 || jresp.Accepted || !jresp.Conflict || jresp.Certificate != nil {
453				t.Fatalf("合格值重交应报冲突且不返回证书：code=%d resp=%+v", jr.code, jresp)
454			}
455	
456			// 限制不被解除：最近证书仍是误差 0.8 的原超差证书，申请仍被拒。
457			rv := reviewSameNumberJSON(t, path, "M-1")
458			if rv.CanUse || !containsStd(rv.Reasons, "超差") {
459				t.Fatalf("冲突重交不能解除超差限制：canUse=%v reasons=%v", rv.CanUse, rv.Reasons)
460			}
461			if containsStd(rv.Reasons, "到期") {
462				t.Fatalf("未来截止日不应混入到期原因：%v", rv.Reasons)
463			}
464			if len(rv.History) != 1 || rv.Latest == nil ||
465				rv.Latest.Error != 0.8 || rv.Latest.Pass {
466				t.Fatalf("最近证书应仍是误差 0.8 的超差原证书：%+v", rv.Latest)
467			}
468			u := runArgs(t, "use", "--id", "M-1", "-f", path, "--json")
469			if u.code != 1 || !strings.Contains(u.stdout, `"allowed": false`) ||
470				!strings.Contains(u.stdout, "超差") {
471				t.Fatalf("重交后正式申请仍应因原超差证书被拒：code=%d stdout=%q",
472					u.code, u.stdout)
473			}
474		})
475	
476		t.Run("到期证书改成未来截止日重交不能恢复资格", func(t *testing.T) {
477			dir := chdirTemp(t)
478			path := filepath.Join(dir, "台账.json")
479			registerAllowed(t, path, "M-1", "0.5")
480			if r := runArgs(t, "status", "-f", path, "--id", "M-1", "--status", "在用"); r.code != 0 {
481				t.Fatalf("切换在用失败 code=%d stderr=%s", r.code, r.stderr)
482			}
483			now := time.Now()
484			oldCal := now.AddDate(-2, 0, 0).Format(calibrate.DateLayout)
485			pastExpiry := now.AddDate(-1, 0, 0).Format(calibrate.DateLayout) // 已到期。
486			futureExpiry := now.AddDate(1, 0, 0).Format(calibrate.DateLayout)
487			expired := sameNumberCertArgs(path, "M-1", "C-1", oldCal, pastExpiry, "规范A", "0.1", "摘要")
488			if r := runArgs(t, expired...); r.code != 0 {
489				t.Fatalf("到期证书录入失败 code=%d stderr=%s", r.code, r.stderr)
490			}
491			if u := runArgs(t, "use", "--id", "M-1", "-f", path); u.code != 1 ||
492				!strings.Contains(u.stderr, "到期") {
493				t.Fatalf("前置条件失效：应因最近证书到期被拒，code=%d stderr=%q",
494					u.code, u.stderr)
495			}
496	
497			// 同号改成未来截止日重交（仍晚于校准日期，内容本身合法）：只能报冲突。
498			updated := sameNumberCertArgs(path, "M-1", "C-1", oldCal, futureExpiry, "规范A", "0.1", "摘要")
499			human := runArgs(t, updated...)
500			if human.code != 1 || !strings.Contains(human.stderr, "内容不同") {
501				t.Fatalf("未来截止日重交应冲突退出 1：code=%d stderr=%q",
502					human.code, human.stderr)
503			}
504			jr, jresp := runCertCLIJSON(t, updated)
505			if jr.code != 1 || jresp.Accepted || !jresp.Conflict || jresp.Certificate != nil {
506				t.Fatalf("未来截止日重交 JSON 应冲突且不返回证书：code=%d resp=%+v",
507					jr.code, jresp)
508			}
509	
510			// 使用资格不恢复：最近证书仍是合格但已到期的原证书，申请仍只因到期被拒。
511			rv := reviewSameNumberJSON(t, path, "M-1")
512			if rv.CanUse || !containsStd(rv.Reasons, "到期") {
513				t.Fatalf("冲突重交不能恢复使用资格：canUse=%v reasons=%v", rv.CanUse, rv.Reasons)
514			}
515			if containsStd(rv.Reasons, "超差") {
516				t.Fatalf("合格证书不应混入超差原因：%v", rv.Reasons)
517			}
518			if len(rv.History) != 1 || rv.Latest == nil ||
519				rv.Latest.Expiry != pastExpiry || !rv.Latest.Expired || !rv.Latest.Pass {
520				t.Fatalf("最近证书应仍是合格但已到期的原证书：%+v", rv.Latest)
521			}
522			certs := readPersistedCerts(t, path)
523			if len(certs) != 1 || certs[0].Expiry != pastExpiry {
524				t.Fatalf("原截止日不得被未来值替换：%+v", certs)
525			}
526			u := runArgs(t, "use", "--id", "M-1", "-f", path, "--json")
527			if u.code != 1 || !strings.Contains(u.stdout, `"allowed": false`) ||
528				!strings.Contains(u.stdout, "到期") {
529				t.Fatalf("重交后正式申请仍应因原证书到期被拒：code=%d stdout=%q",
530					u.code, u.stdout)
531			}
532		})
533	}
